export function OperationsSyncEntry() {
  const searchParams = useSearchParams();
  const locationSearch = searchParams.toString();
  const [state, setState] = useState<"loading" | "center" | "error">("loading"), [error, setError] = useState("");
  const seq = useRef(0);
  const probe = useCallback(async () => { const n = ++seq.current; const view = pageFromLocation(); if (["purchase-orders", "suppliers", "first-mile", "fba-boxing"].includes(view) || operationsEntries.some(entry => entry.view === view && entry.pending)) { setState("center"); return; } setState("loading"); try {
    const response = await fetch(`${base}?section=settings`, { headers: headers(), cache: "no-store" }); const p = await response.json();
    if (n !== seq.current) return;
    if (!response.ok) throw new Error(p.error ?? "无法读取同步中心配置。"); setState("center");
  } catch (e) { if (n === seq.current) { setError(e instanceof Error ? e.message : "读取失败。"); setState("error"); } } }, []);
  const invalidateProbe = useCallback(() => { ++seq.current; }, []);
  useEffect(() => { void probe(); window.addEventListener(workspaceScopeChangedEventName, probe); return () => { invalidateProbe(); window.removeEventListener(workspaceScopeChangedEventName, probe); }; }, [probe, invalidateProbe, locationSearch]);
  if (state === "loading") return <p className="p-4 text-sm text-muted" role="status">读取工作区同步配置…</p>;
  if (state === "error") return <div className="space-y-4 p-4 text-sm"><p role="alert">{error}</p><Panel title="Amazon SP-API 配置"><AmazonConfigurationHelp /></Panel><Button variant="secondary" onClick={() => void probe()}>重新读取</Button></div>;
  return <SyncCenterWorkbench />;
}

